  INSERT INTO books (slug, title, subtitle)
  VALUES ('beginners-guide-reading-sheet-music','Beginners Guide to Reading Sheet Music','Beginners Guide to Reading Sheet Music')
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title
